function check([operations, args], actual, expected) {
  const [m, n] = args[0];
  if (!Array.isArray(actual) || actual.length !== operations.length || actual[0] !== null) return false;
  const total = m * n;
  // Each flip's rank among the free cells (row-major) should be uniform; count it in one of 8 equal bins.
  const BINS = 8;
  const hits = new Array(BINS).fill(0), mean = new Array(BINS).fill(0), spread = new Array(BINS).fill(0);
  let flipped = new Set();
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'reset') {
      if (actual[i] !== null) return false;
      flipped = new Set();
      continue;
    }
    const cell = actual[i];
    if (!Array.isArray(cell) || cell.length !== 2 || !Number.isInteger(cell[0]) || !Number.isInteger(cell[1])) return false;
    const [row, col] = cell;
    if (row < 0 || row >= m || col < 0 || col >= n) return false;
    const index = row * n + col;
    if (flipped.has(index)) return false;
    let before = 0;
    for (const f of flipped) if (f < index) before++;
    const free = total - flipped.size, rank = index - before;
    flipped.add(index);
    hits[Math.floor((rank * BINS) / free)]++;
    for (let b = 0; b < BINS; b++) {
      const p = (Math.ceil(((b + 1) * free) / BINS) - Math.ceil((b * free) / BINS)) / free;
      mean[b] += p;
      spread[b] += p * (1 - p);
    }
  }
  // Each bin's count stays within 5.5 standard deviations (+3 slack) of a fair choice; a chi-square adds power.
  let chi = 0, cells = 0;
  for (let b = 0; b < BINS; b++) {
    if (Math.abs(hits[b] - mean[b]) > 5.5 * Math.sqrt(spread[b]) + 3) return false;
    if (mean[b] >= 5) { chi += (hits[b] - mean[b]) ** 2 / mean[b]; cells++; }
  }
  if (cells > 1 && chi > cells + 6 * Math.sqrt(2 * cells) + 8) return false;
  return true;
}

