function validate([operations, args]) {
  if (!Array.isArray(operations) || operations[0] !== 'Solution' || !Array.isArray(args) || args.length !== operations.length) return 'Start with "Solution" and give one argument list per operation.';
  const [m, n] = args[0];
  if (!Number.isInteger(m) || !Number.isInteger(n) || m < 1 || n < 1 || m > 10000 || n > 10000) return 'm and n are whole numbers from 1 to 10^4.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to flip and reset.';
  let flipped = 0;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'reset') flipped = 0;
    else if (operations[i] === 'flip') {
      if (flipped === m * n) return 'Every flip needs at least one cell that is still 0.';
      flipped++;
    } else return 'After the constructor, only flip and reset are called.';
  }
  return null;
}

