class Solution {
  constructor(m, n) {
    this.rows = m;
    this.cols = n;
    this.remaining = m * n;
    this.moved = new Map();
  }

  flip() {
    const pick = Math.floor(Math.random() * this.remaining);
    this.remaining--;
    const cell = this.moved.get(pick) ?? pick;
    const last = this.moved.get(this.remaining) ?? this.remaining;
    this.moved.set(pick, last);
    return [Math.floor(cell / this.cols), cell % this.cols];
  }

  reset() {
    this.remaining = this.rows * this.cols;
    this.moved.clear();
  }
}

