class Solution {
  constructor(m, n) {
    this.m = m;
    this.n = n;
    this.taken = new Set();
  }
  flip() {
    // Rejection sampling: draw a row and a column until the cell is still 0.
    for (;;) {
      const i = Math.floor(Math.random() * this.m), j = Math.floor(Math.random() * this.n);
      const key = i + ',' + j;
      if (!this.taken.has(key)) {
        this.taken.add(key);
        return [i, j];
      }
    }
  }
  reset() {
    this.taken = new Set();
  }
}

