function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  let m, n, calls;
  if (size === 'large') {
    const shape = pick(4);
    if (shape === 0) { m = 10000 - pick(3); n = 10000 - pick(3); }
    else if (shape === 1) { m = 1 + pick(3); n = 1 + pick(10000); }
    else if (shape === 2) { m = 1 + pick(10000); n = 1 + pick(3); }
    else { m = 1 + pick(6); n = 1 + pick(6); }
    calls = 400 + pick(100);
  } else {
    m = 1 + pick(4);
    n = 1 + pick(4);
    calls = 1 + pick(rand() < 0.5 ? 12 : 300);
  }
  const resetRate = rand() < 0.3 ? 0 : rand() * 0.2;
  const operations = ['Solution'], args = [[m, n]];
  let flipped = 0;
  while (operations.length <= calls) {
    // A full grid must be reset before the next flip.
    if (flipped === m * n || (flipped > 0 && rand() < resetRate)) {
      operations.push('reset');
      flipped = 0;
    } else {
      operations.push('flip');
      flipped++;
    }
    args.push([]);
  }
  return [operations, args];
}
